    26	// Reads all the tokens of the file, ignoring the lines that start with '#'.
    27	static bool ReadTokens(const string &filename, vector<string> &tokens)
    28	{
    29		ifstream in(filename.c_str());
    30		if (!in)
    31			return false;
    32		string line;
    33		while (getline(in, line))
    34		{
    35			size_t p = line.find_first_not_of(" \t\r");
    36			if (p == string::npos || line[p] == '#')
    37				continue;
    38			istringstream ss(line);
    39			string tok;
    40			while (ss >> tok)
    41				tokens.push_back(tok);
    42		}
    43		return true;
    44	}
