    46	// Input format (lines starting with '#' are comments):
    47	//   n C k
    48	//   s_1 s_2 ... s_n
    49	//   k lines, one per class:  m_t i_1 ... i_{m_t}
    50	static bool ReadInstance(const string &filename, BinPackingData &data, string &err)
    51	{
    52		vector<string> tok;
    53		if (!ReadTokens(filename, tok))
    54		{
    55			err = "cannot open " + filename;
    56			return false;
    57		}
    58		size_t pos = 0;
    59		long long v;
    60		auto next = [&](long long &x) -> bool
    61		{
    62			if (pos >= tok.size())
    63			{
    64				err = "unexpected end of file";
    65				return false;
    66			}
    67			char *end;
    68			errno = 0;
    69			x = strtoll(tok[pos].c_str(), &end, 10);
    70			if (errno == ERANGE || end == tok[pos].c_str() || *end != '\0')
    71			{
    72				err = "invalid number: " + tok[pos];
    73				return false;
    74			}
    75			pos++;
    76			return true;
    77		};
    78		if (!next(v))
    79			return false;
    80		if (v < 1 || v >= INT_MAX)
    81		{
    82			err = "invalid n";
    83			return false;
    84		}
    85		data.n = (int)v;
    86		if (!next(v))
    87			return false;
    88		data.C = v;
    89		if (!next(v))
    90			return false;
    91		if (v < 0 || v > INT_MAX)
    92		{
    93			err = "invalid k";
    94			return false;
    95		}
    96		data.k = (int)v;
    97		if (data.n < 1 || data.C < 1 || data.k < 0)
    98		{
    99			err = "invalid n, C or k";
   100			return false;
   101		}
   102		data.size.assign(data.n + 1, 0);
   103		for (int i = 1; i <= data.n; i++)
   104		{
   105			if (!next(v))
   106				return false;
   107			if (v < 1 || v > data.C)
   108			{
   109				err = "size of an item is not in 1..C";
   110				return false;
   111			}
   112			data.size[i] = v;
   113		}
   114		data.cls.assign(data.k, vector<int>());
   115		for (int t = 0; t < data.k; t++)
   116		{
   117			if (!next(v))
   118				return false;
   119			long long m = v;
   120			if (m < 0)
   121			{
   122				err = "invalid size of a class";
   123				return false;
   124			}
   125			set<int> items; // removes repeated items of a class
   126			for (long long a = 0; a < m; a++)
   127			{
   128				if (!next(v))
   129					return false;
   130				if (v < 1 || v > data.n)
   131				{
   132					err = "item out of range in a class";
   133					return false;
   134				}
   135				items.insert((int)v);
   136			}
   137			data.cls[t].assign(items.begin(), items.end());
   138		}
   139		if (pos != tok.size())
   140			cout << "Warning: extra data at the end of the input file" << endl;
   141		data.Prepare();
   142		return true;
   143	}
