   150	static bool WriteSolution(const string &filename, const BinPackingData &data)
   151	{
   152		ofstream out(filename.c_str());
   153		if (!out)
   154			return false;
   155		out << "# valor da solucao (numero de recipientes)\n"
   156		    << data.best_value << "\n"
   157		    << "# limitante inferior\n"
   158		    << data.lower_bound << "\n"
   159		    << "# numero de recipientes\n"
   160		    << data.best_solution.size() << "\n"
   161		    << "# itens de cada recipiente\n";
   162		for (size_t b = 0; b < data.best_solution.size(); b++)
   163		{
   164			for (size_t a = 0; a < data.best_solution[b].size(); a++)
   165				out << (a ? " " : "") << data.best_solution[b][a];
   166			out << "\n";
   167		}
   168		return true;
   169	}
