   244	void Usage(const char *prog)
   245	{
   246		std::cout << "Usage: " << prog << " -f <input file> -o <output file> -t <seconds> [-r <seed>]"
   247		          << std::endl
   248		          << "  -f  input file with the instance" << std::endl
   249		          << "  -o  output file where the best solution is written" << std::endl
   250		          << "  -t  maximum running time T, in seconds" << std::endl
