   255	std::optional<CommandLineOptions> ParseCommandLine(int argc, const char *const argv[])
   256	{
   257		CommandLineOptions options;
   258		for (int i = 1; i < argc; i++)
   259		{
   260			std::string arg = argv[i];
   261			if (arg == "-f" && i + 1 < argc)
   262				options.input_file = argv[++i];
   263			else if (arg == "-o" && i + 1 < argc)
   264				options.output_file = argv[++i];
   265			else if (arg == "-t" && i + 1 < argc)
   266			{
   267				const char *text = argv[++i];
   268				char *end = nullptr;
   269				errno = 0;
   270				options.time_limit = std::strtod(text, &end);
   271				// steady_clock duration and deadline arithmetic must be representable.
   272				double max_seconds =
   273				    std::chrono::duration<double>(std::chrono::steady_clock::time_point::max() -
   274					                              std::chrono::steady_clock::now())
   275				        .count();
   276				if (errno || end == text || *end || !std::isfinite(options.time_limit) ||
   277				    options.time_limit < 0 || options.time_limit >= max_seconds)
   278				{
   279					std::cerr << "Invalid time limit\n";
   280					return std::nullopt;
   281				}
   282			}
   283			else if (arg == "-r" && i + 1 < argc)
   284			{
   285				const char *text = argv[++i];
   286				char *end = nullptr;
   287				errno = 0;
   288				unsigned long value = std::strtoul(text, &end, 10);
   289				if (errno || end == text || *end || text[0] == '-' ||
   290				    value > std::numeric_limits<unsigned>::max())
   291				{
   292					std::cerr << "Invalid seed\n";
   293					return std::nullopt;
   294				}
   295				options.seed = static_cast<unsigned>(value);
   296			}
   297			else
   298			{
   299				std::cout << "Unknown or incomplete argument: " << arg << std::endl;
   300				Usage(argv[0]);
   301				return std::nullopt;
   302			}
   303		}
   304		if (options.input_file.empty() || options.output_file.empty() || options.time_limit < 0)
   305		{
   306			Usage(argv[0]);
   307			return std::nullopt;
   308		}
   309		return options;
   310	}
