    31	struct Node
    32	{
    33		std::vector<std::pair<int, int>> together, apart;
    34		int bound;
    35		unsigned long long id;
    36	};
    37	struct BestBound
    38	{
    39		bool operator()(const Node &a, const Node &b) const
    40		{
    41			return a.bound != b.bound ? a.bound > b.bound : a.id > b.id;
    42		}
