    44	struct Groups
    45	{
    46		std::vector<Pattern> items;
    47		std::vector<long long> size;
    48		std::vector<std::vector<bool>> conflict;
    49		std::vector<int> group_of;
    50		bool valid = true;
    51		Groups(const BinPackingData &d, const Node &node, Clock::time_point deadline)
    52		{
    53			std::vector<int> parent(d.n + 1);
    54			std::iota(parent.begin(), parent.end(), 0);
    55			std::function<int(int)> root = [&](int i)
    56			{ return parent[i] == i ? i : parent[i] = root(parent[i]); };
    57			for (auto [i, j] : node.together)
    58				parent[root(i)] = root(j);
    59			std::map<int, int> ids;
    60			group_of.resize(d.n + 1);
    61			for (int i = 1; i <= d.n; ++i)
    62			{
    63				checkTime(deadline);
    64				int r = root(i);
    65				auto it = ids.emplace(r, static_cast<int>(ids.size())).first;
    66				int g = it->second;
    67				if (g == static_cast<int>(items.size()))
    68				{
    69					items.emplace_back();
    70					size.push_back(0);
    71				}
    72				group_of[i] = g;
    73				items[g].push_back(i);
    74				if (d.size[i] > d.C - size[g])
    75				{
    76					valid = false;
    77					return;
    78				}
    79				size[g] += d.size[i];
    80			}
    81			conflict.assign(items.size(), std::vector<bool>(items.size(), false));
    82			auto forbid = [&](int i, int j)
    83			{
    84				checkTime(deadline);
    85				int a = group_of[i], b = group_of[j];
    86				if (a == b)
    87					valid = false;
    88				else
    89					conflict[a][b] = conflict[b][a] = true;
    90			};
    91			for (const auto &s : d.cls)
    92				for (size_t i = 0; i < s.size(); ++i)
    93					for (size_t j = i + 1; j < s.size(); ++j)
    94						forbid(s[i], s[j]);
    95			for (auto [i, j] : node.apart)
    96				forbid(i, j);
    97		}
    98		Pattern expand(const Pattern &p) const
    99		{
   100			Pattern result;
   101			for (int g : p)
   102				result.insert(result.end(), items[g].begin(), items[g].end());
   103			std::sort(result.begin(), result.end());
   104			return result;
   105		}
   106		bool admissible(const Pattern &p, Pattern &out) const
   107		{
   108			std::vector<int> counts(items.size(), 0);
   109			for (int i : p)
   110				++counts[group_of[i]];
   111			out.clear();
   112			for (size_t g = 0; g < counts.size(); ++g)
   113			{
   114				if (!counts[g])
   115					continue;
   116				if (counts[g] != static_cast<int>(items[g].size()))
   117					return false;
   118				for (int h : out)
   119					if (conflict[g][h])
   120						return false;
   121				out.push_back(static_cast<int>(g));
   122			}
   123			return !out.empty();
   124		}
   125	};
