   140	// Fractional knapsack, ignoring conflicts, upper-bounds all feasible pricing
   141	// patterns. Positive duals only: removing a nonpositive group preserves validity.
   142	struct Pricing
   143	{
   144		const Groups &g;
   145		const std::vector<double> &u;
   146		long long capacity;
   147		Clock::time_point deadline;
   148		Pattern order, chosen, best_pattern;
   149		long double best = 0, upper = 0;
   150		bool complete = true;
   151		Pricing(const Groups &groups, const std::vector<double> &duals, long long c,
   152		        Clock::time_point d)
   153		    : g(groups), u(duals), capacity(c), deadline(d)
   154		{
   155			for (size_t i = 0; i < u.size(); ++i)
   156				if (u[i] > 0)
   157					order.push_back(static_cast<int>(i));
   158			std::sort(order.begin(), order.end(),
   159			          [&](int a, int b)
   160			          {
   161				          long double x = static_cast<long double>(u[a]) * g.size[b];
   162				          long double y = static_cast<long double>(u[b]) * g.size[a];
   163				          return x != y ? x > y : a < b;
   164			          });
   165			upper = fractional(0, capacity);
   166		}
   167		long double fractional(size_t pos, long long remaining) const
   168		{
   169			long double value = 0;
   170			for (size_t p = pos; p < order.size() && remaining > 0; ++p)
   171			{
   172				int i = order[p];
   173				if (g.size[i] <= remaining)
   174				{
   175					remaining -= g.size[i];
   176					value += u[i];
   177				}
   178				else
   179				{
   180					value += static_cast<long double>(u[i]) * remaining / g.size[i];
   181					break;
   182				}
   183			}
   184			return value;
   185		}
   186		void dfs(size_t pos, long long remaining, long double value)
   187		{
   188			if (Clock::now() >= deadline)
   189			{
   190				complete = false;
   191				return;
   192			}
   193			if (value > best)
   194			{
   195				best = value;
   196				best_pattern = chosen;
   197			}
   198			if (pos == order.size() || value + fractional(pos, remaining) <= best + 1e-10L)
   199				return;
   200			int i = order[pos];
   201			bool ok = g.size[i] <= remaining;
   202			for (int j : chosen)
   203				if (g.conflict[i][j])
   204				{
   205					ok = false;
   206					break;
   207				}
   208			if (ok)
   209			{
   210				chosen.push_back(i);
   211				dfs(pos + 1, remaining - g.size[i], value + u[i]);
   212				chosen.pop_back();
   213				if (!complete)
   214					return;
   215			}
   216			dfs(pos + 1, remaining, value);
   217		}
   218		void exact()
   219		{
   220			dfs(0, capacity, 0);
   221			// Account for the small pruning tolerance and floating arithmetic.
   222			if (complete)
   223				upper = best + 1e-8L;
   224		}
   225	};
   226	
   227	template <typename AddColumn>
   228	std::size_t addHeuristicColumns(const Pricing &pricing, std::mt19937_64 &rng, const AddColumn &add)
   229	{
   230		const auto &groups = pricing.g;
   231		const auto &dual = pricing.u;
   232		std::size_t added = 0;
   233		// Try density order first, then dual value, then shuffled orders.
   234		for (int round = 0; round < 12 && Clock::now() < pricing.deadline; ++round)
   235		{
   236			Pattern order = pricing.order;
   237			if (round == 1)
   238				std::sort(order.begin(), order.end(),
   239				          [&](int a, int b) { return dual[a] != dual[b] ? dual[a] > dual[b] : a < b; });
   240			else if (round > 1)
   241				std::shuffle(order.begin(), order.end(), rng);
   242			Pattern p;
   243			long long remaining = pricing.capacity;
   244			long double value = 0;
   245			for (int g : order)
   246			{
   247				if (groups.size[g] > remaining)
   248					continue;
   249				bool ok = true;
   250				for (int h : p)
   251					if (groups.conflict[g][h])
   252					{
   253						ok = false;
   254						break;
   255					}
   256				if (ok)
   257				{
   258					p.push_back(g);
   259					remaining -= groups.size[g];
   260					value += dual[g];
   261				}
   262			}
   263			if (value > 1 + RC_EPS && add(p))
   264				++added;
   265		}
   266		return added;
   267	}
   268	
   269	int certifiedBound(const std::vector<double> &u, long double alpha, int inherited)
   270	{
   271		long double sum = 0;
   272		for (double x : u)
   273			sum += x;
   274		long double safe_alpha = std::max(1.0L, alpha) + 1e-8L;
   275		return std::max(inherited, static_cast<int>(std::ceil(sum / safe_alpha - INT_EPS)));
   276	}
   277	
   278	struct Stats
   279	{
   280		size_t nodes = 0, lp = 0, heuristic = 0, exact = 0, branches = 0;
   281	};
