   284	void BranchAndPrice(BinPackingData &data, Clock::time_point deadline)
   285	{
   286		std::cout << "Starting BranchAndPrice\n";
   287		std::priority_queue<Node, std::vector<Node>, BestBound> open;
   288		unsigned long long next_id = 1;
   289		open.push(Node{{}, {}, data.lower_bound, 0});
