   327					open.pop();
   328					continue;
   329				}
   330				GRBModel model(env);
   331				model.setCallback(&callback);
   332				model.set(GRB_IntParam_Method, 1); // dual simplex; incremental columns
   333				model.set(GRB_DoubleParam_FeasibilityTol, 1e-9);
   334				model.set(GRB_DoubleParam_OptimalityTol, 1e-9);
