   361				std::vector<Pattern> snapshot(pool.begin(), pool.end());
   362				for (const auto &p : snapshot)
   363				{
   364					checkTime(deadline);
   365					Pattern q;
   366					if (groups.admissible(p, q))
   367						add(q);
   368				}
