   398					{
   399						stopped = true;
   400						break;
   401					}
   402					++stats.exact;
   403					pricing.exact();
   404					node.bound = certifiedBound(dual, pricing.upper, node.bound);
   405					if (node.bound >= data.best_value)
   406					{
   407						solved = true;
   408						break;
   409					}
   410					if (pricing.best > 1 + RC_EPS)
   411					{
   412						if (!add(pricing.best_pattern))
   413							throw std::runtime_error("pricing repeated a negative reduced-cost column");
