   430					{
   431						x[p] = vars[p].get(GRB_DoubleAttr_X);
   432						if (std::abs(x[p] - std::round(x[p])) > INT_EPS)
   433							integral = false;
   434					}
   435					if (integral)
   436					{
   437						std::vector<Pattern> bins;
   438						for (size_t p = 0; p < x.size(); ++p)
   439							if (x[p] > 0.5)
   440								bins.push_back(groups.expand(patterns[p]));
   441						std::string error;
   442						if (!data.CheckSolution(bins, error))
   443							throw std::runtime_error(error);
