   446						break;
   447					}
   448					std::map<std::pair<int, int>, double> phi;
   449					for (size_t p = 0; p < x.size(); ++p)
   450						if (x[p] > 1e-9)
   451							for (size_t a = 0; a < patterns[p].size(); ++a)
   452								for (size_t b = a + 1; b < patterns[p].size(); ++b)
   453									phi[{patterns[p][a], patterns[p][b]}] += x[p];
   454					std::pair<int, int> pair{-1, -1};
   455					double distance = 1;
   456					for (auto entry : phi)
   457					{
   458						double v = entry.second;
   459						if (v > INT_EPS && v < 1 - INT_EPS && std::abs(v - 0.5) < distance)
   460						{
   461							pair = entry.first;
   462							distance = std::abs(v - 0.5);
   463						}
   464					}
   465					if (pair.first < 0)
   466						throw std::runtime_error("no fractional Ryan-Foster pair (numerical issue)");
