   468					Node together = node, apart = node;
   469					together.together.emplace_back(i, j);
   470					together.id = next_id++;
   471					apart.apart.emplace_back(i, j);
   472					apart.id = next_id++;
   473					open.pop();
   474					open.push(std::move(together));
   475					open.push(std::move(apart));
   476					++stats.branches;
   477					solved = true;
   478					branched = true;
   479					break;
   480				}
   481				if (branched)
   482					continue; // parent already replaced by both children
   483				open.pop();
   484				if (!solved)
   485				{
   486					open.push(node);
   487					stopped = true;
   488				}
   489				if (stopped)
   490					break;
   491			}
   492		}
   493		catch (const TimeExpired &)
   494		{
   495			// The current node is still in the frontier with its inherited bound.
   496		}
   497		catch (const GRBException &e)
   498		{
   499			std::cerr << "Gurobi: " << e.getMessage() << " (" << e.getErrorCode()
   500			          << "). Returning incumbent and certified frontier bound.\n";
   501		}
   502		catch (const std::exception &e)
   503		{
   504			std::cerr << "Search interrupted: " << e.what() << ". Returning certified frontier.\n";
   505		}
   506		data.lower_bound =
   507		    open.empty() ? data.best_value
   508			             : std::max(data.lower_bound, std::min(data.best_value, open.top().bound));
   509		std::cout << "[B&P] nodes=" << stats.nodes << " LPs=" << stats.lp
   510		          << " heuristic_columns=" << stats.heuristic << " exact_calls=" << stats.exact
   511		          << " branches=" << stats.branches << " pool=" << pool.size()
   512		          << " LB=" << data.lower_bound << " UB=" << data.best_value << '\n';
   513	}

